const incoming = $('Calendar Webhook').first().json;
const request = incoming.body || {};
const endpoint = String($json.adapterUrl || '').trim();
const deny = code => [{ json: { valid:false, statusCode:400, result:{ok:false,confirmed:false,code} } }];
const actions = ['check_availability','book_appointment','cancel_appointment','reschedule_appointment'];
if (request.version !== 1 || !actions.includes(request.action)) return deny('unsupported_calendar_action');
if (typeof request.deploymentId !== 'string' || !request.deploymentId || typeof request.idempotencyKey !== 'string' || !request.idempotencyKey) return deny('missing_request_identity');
let target;
try { target = new URL(endpoint); } catch { return deny('adapter_not_configured'); }
if (target.protocol !== 'https:' || target.username || target.password) return deny('unsafe_adapter_url');
const data = request.data || {};
if (['book_appointment','reschedule_appointment'].includes(request.action) && data.callerConfirmedSlot !== true) return deny('slot_not_confirmed');
if (['book_appointment','reschedule_appointment'].includes(request.action) && (!data.startTime || !data.timezone || !Number.isFinite(Date.parse(data.startTime)))) return deny('invalid_appointment_time');
if (request.action === 'book_appointment' && (!data.callerName || !data.service)) return deny('missing_booking_details');
if (request.action === 'check_availability' && (!data.preferredDate || !data.service || !data.timezone)) return deny('missing_availability_details');
if (['cancel_appointment','reschedule_appointment'].includes(request.action) && !data.bookingId) return deny('missing_booking_id');
return [{json:{valid:true,request,endpoint:target.toString()}}];

const response = $json;
const action = $('Validate Calendar Request').first().json.request.action;
const body = response.body || {};
const good = Number(response.statusCode) >= 200 && Number(response.statusCode) < 300 && body.ok === true && body.confirmed === true;
if (!good) return [{json:{statusCode:502,result:{ok:false,confirmed:false,code:'calendar_adapter_not_confirmed'}}}];
const result = {ok:true,confirmed:true,action};
for (const key of ['bookingId','start','end','message']) if (typeof body[key] === 'string') result[key] = body[key].slice(0,key === 'message' ? 1000 : 300);
if (typeof body.available === 'boolean') result.available = body.available;
if (Array.isArray(body.slots)) result.slots = body.slots.slice(0,12).filter(s=>s && typeof s.start === 'string' && Number.isFinite(Date.parse(s.start))).map(s=>({start:s.start,end:typeof s.end === 'string'?s.end:'',label:typeof s.label === 'string'?s.label.slice(0,200):''}));
return [{json:{statusCode:200,result}}];
